    // Create two arrays to store the maximum sum of increasing subsequences ending at each index
    let inc = new Array(n).fill(0);
    // Create another array to store the maximum sum of decreasing subsequences starting from each index
    let dec = new Array(n).fill(0);

    for (let i = 0; i < n; i++) {
        inc[i] = arr[i];
        for (let j = 0; j < i; j++) {
            if (arr[j] < arr[i]) {
                inc[i] = Math.max(inc[i], inc[j] + arr[i]);
            }
        }
    }

    for (let i = n - 1; i >= 0; i--) {
        dec[i] = arr[i];
        for (let j = i + 1; j < n; j++) {
            if (arr[j] < arr[i]) {
                dec[i] = Math.max(dec[i], dec[j] + arr[i]);
            }
        }
    }

    // Find the maximum sum of bitonic subsequences
    let max_sum_bitonic = 0;
    for (let i = 0; i < n; i++) {
