function next_smallest_palindrome(num) {
    let str = num.toString();
    let len = str.length;

    // Find the first non-palindromic digit from the right
    for (let i = len - 2; i >= 0; i--) {
        if (str[i] !== str[len - 1 - i]) {
            break;
        }
    }

    // If no such digit is found, return the next palindrome by appending a '9' to the right
    if (i < 0) {
        return parseInt(str + '9');
    }

    // Otherwise, find the smallest number that can be formed by replacing the non-palindromic digit with a '1'
    let carry = 1;
    for (let j = i; j >= 0; j--) {
        str[j] = '1';
        carry = 0;
    }

    // If the first digit is '9', prepend a '1' to the string
    if (str[0] === '9') {
        return parseInt('1' + str.slice(1));
    }

    return parseInt(str);
}

function next_smallest_palindrome(num) {
  let strNum = num.toString();
  let len = strNum.length;

  // If the number is already a palindrome, increment by 1
  if (strNum === strNum.split('').reverse().join('')) {
    return num + 1;
  }

  // Find the longest palindromic suffix and remove it
  let suffix = '';
  for (let i = len - 2; i >= 0; i--) {
    if (strNum[i] !== strNum[len - 1 - i]) break;
    suffix += strNum[i];
  }

  // Remove the palindromic suffix and add the smallest possible prefix to form the next palindrome
  let prefix = '';
  for (let i = len - 2; i >= 0; i--) {
    if (strNum[i] !== strNum[len - 1 - i]) break;
    prefix += strNum[i];
  }

  // Add the smallest possible suffix to form the next palindrome
  let nextSuffix = '';
  for (let i = len - 2; i >= 0; i--) {
    if (strNum[i] !== strNum[len - 1 - i]) break;
    nextSuffix += '9';
  }

  // Return the next smallest palindrome
  return parseInt(strNum.substring(0, len - suffix.length) + prefix + nextSuffix);
}

