function get_total_number_of_sequences(m, n) {
  // Initialize an array to store the number of sequences ending with each value from 1 to m
  const dp = new Array(m + 1).fill(0);

  // Base case: There is one sequence of length 1 ending with each value from 1 to m
  for (let i = 1; i <= m; i++) {
    dp[i] = 1;
  }

  // Fill the dp array using dynamic programming
  for (let i = 2; i <= n; i++) {
    for (let j = 1; j <= m; j++) {
      if (j >= 2 * (i - 1)) {
        dp[j] += dp[j - 1];
      }
    }
  }

  // The total number of sequences is the sum of all values in the dp array
  let total_sequences = 0;
  for (let i = 1; i <= m; i++) {
    total_sequences += dp[i];
  }

  return total_sequences;
}

function get_total_number_of_sequences(m, n) {
  if (m < 2 || n < 1) return 0;

  const dp = Array(n + 1).fill(0);
  dp[0] = 1; // There is one way to have an empty sequence

  for (let i = 1; i <= n; i++) {
    for (let j = Math.max(i * 2, 1); j <= m; j++) {
      dp[i] += dp[j - i];
    }
  }

  return dp[n];
}

