    if ((mid === 0 || arr[mid] !== arr[mid - 1]) && (mid === arr.length - 1 || arr[mid] !== arr[mid + 1])) {
      return arr[mid];
    }

    // Determine which half to search based on the value at mid
    if (arr[mid] > arr[mid - 1]) {
      // If the first part is sorted, move left to mid + 1
      if (mid % 2 === 0) {
        right = mid - 1;
      } else {
        left = mid + 1;
      }
    } else {
      // If the second part is sorted, move right to mid - 1
      if (mid % 2 === 1) {
        right = mid - 1;
      } else {
        left = mid + 1;
      }
    }
  }

