function maxAverageOfPath(cost) {
    const N = cost.length;
    let dp = Array.from({ length: N }, () => Array(N).fill(0));

    // Base case: starting from the top-left cell
    dp[0][0] = cost[0][0];

    // Fill the first row and first column
    for (let i = 1; i < N; i++) {
        dp[i][0] = dp[i-1][0] + cost[i][0];
        dp[0][i] = dp[0][i-1] + cost[0][i];
    }

    // Fill the rest of the matrix
    for (let i = 1; i < N; i++) {
        for (let j = 1; j < N; j++) {
            dp[i][j] = Math.max(dp[i-1][j], dp[i][j-1]) + cost[i][j];
        }
    }

    // The maximum average path will be the value in the bottom-right cell of the matrix
    return dp[N-1][N-1] / (N * N);
}

