function sort_matrix(M) {
  // Calculate the sum of each row in the matrix
  const rowSums = M.map(row => row.reduce((acc, val) => acc + val, 0));

  // Sort the matrix based on the sum of its rows
  return rowSums.sort((a, b) => a - b).map(sum => M.filter(row => row.reduce((acc, val) => acc + val, 0) === sum));
}

function sort_matrix(M) {
  // Sort the matrix based on the sum of each row
  return M.sort((a, b) => a.reduce((sum, val) => sum + val, 0) - b.reduce((sum, val) => sum + val, 0));
}

