function two_unique_nums(nums) {
  const uniqueNums = new Set();
  for (let i = 0; i < nums.length; i++) {
    for (let j = i + 1; j < nums[i].length; j++) {
      uniqueNums.add(nums[i][j]);
    }
  }
  return Array.from(uniqueNums);
}

function two_unique_nums(nums) {
  const uniqueNums = new Set();
  nums.forEach(arr => arr.forEach(num => uniqueNums.add(num)));
  return Array.from(uniqueNums);
}

function max_sum_increasing_subseq(a, n, index, k) {
  if (index >= n || k >= n) return 0;

  let sum = a[index];
  for (let j = index + 1; j < n && a[j] > a[index]; j++) {
    sum += max_sum_increasing_subseq(a, n, j, k);
  }

  if (k < n && a[k] > a[index]) {
    sum += max_sum_increasing_subseq(a, n, k, k);
  }

  return Math.max(sum, max_sum_increasing_subseq(a, n, index + 1, k));
}
